-- Rascunho anual 2026. Uma única base de consultas: o caderno Estudo e publicação.
-- Não copia as queries analíticas nem altera as prévias pública/profissional Q3.
-- Depois de revisar e congelar os recortes, altere a referência de fonte abaixo
-- para um pacote compatível; preserve os cortes reais de cada indicador.
-- Executar + congelar esta célula atualiza SOMENTE o rascunho interno do anual.
WITH fonte AS (
 SELECT result->'rows'->0->'payload' AS p FROM estudo.notebook_runs
 WHERE id=233 AND cell_id=251 AND frozen AND status='ok' AND NOT truncated AND row_count=1
)
SELECT p || jsonb_build_object('meta',p->'meta' || jsonb_build_object('edicao_trabalho',
'{"edicao": "anual-2026", "estado": "rascunho_interno", "periodo_alvo_inicio": "2026-01-01", "periodo_alvo_fim": "2026-12-31", "base_inicial_run": 233, "base_inicial_celula": 251, "aviso": "Edição anual em preparação. Os dados disponíveis ainda têm corte Jan–Set; temas em revisão não estão liberados para divulgação.", "temas": [{"id": "inscricoes", "titulo": "Preços de inscrição, kits e lotes", "status": "Em revisão", "secao": 58, "celulas": [336, 340, 366, 367], "pendencia": "Ampliar a amostra de categoria geral; separar descontos, kids, kits e lotes; reconciliar preço resumido e opções.", "aceite": "Menor preço geral capturado por prova; mediana e cobertura explícitas. Taxas e descontos identificados antes de concluir."}, {"id": "cna", "titulo": "Faixas Corrida no Ar", "status": "Em revisão", "secao": 57, "celulas": [351], "pendencia": "Conferir flags PCD, modalidade e elegibilidade para ranking antes de recalcular as faixas.", "aceite": "População homogênea documentada e exclusões auditadas; uma faixa por resultado."}, {"id": "ritmo42", "titulo": "Ritmo nacional dos 42 km", "status": "Em revisão", "secao": 57, "celulas": [351, 404, 405], "pendencia": "Corrigir resultados de 5 km rotulados como 42 km e eventos MTB cadastrados como rua.", "aceite": "Validar a distância efetiva do resultado; congelar nova distribuição e conferir casos divergentes."}, {"id": "maratonas", "titulo": "Cadastro e universo das maratonas", "status": "Em revisão", "secao": 57, "celulas": [404, 405], "pendencia": "Revisar os 16 cadastros sem percurso correspondente e separar calendário, coleta e elegibilidade.", "aceite": "Resolver ou justificar cada divergência. O Top 10 revisado, inclusive Floripa, já permanece no Q3."}, {"id": "floripa", "titulo": "Floripa — importação operacional", "status": "Acompanhar", "secao": 61, "celulas": [401, 402], "pendencia": "Recolher/corrigir a importação operacional; desempenho do estudo já recuperado da RaceTag.", "aceite": "Conferir população 42K geral/elite e tempo líquido antes de trocar a fonte congelada."}, {"id": "q4", "titulo": "Quarto trimestre e fechamento anual", "status": "Aguardando período", "secao": 57, "celulas": [343, 350, 351, 353, 357, 378, 384, 387], "pendencia": "Incluir outubro–dezembro e refazer os comparativos com o mesmo período em 2025.", "aceite": "Corte até 31/12/2026, coletas por bloco e comparativos equivalentes; não apresentar o Q3 como ano completo."}, {"id": "verticais", "titulo": "Novos recortes e estudos verticais", "status": "Backlog", "secao": 59, "celulas": [339], "pendencia": "Priorizar hipóteses de conteúdo da referência Ticket Sports e possíveis verticais.", "aceite": "Definir pergunta, população e fonte disponível antes de prometer um novo capítulo."}]}'::jsonb)) AS payload FROM fonte